contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit `depositAmount` into c, then attempt withdraw and assert invariant.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Read balance of this test address in c before deposit (should be 0 initially but we don't assume)
        uint256 beforeRecorded = c.balances(address(this));
        // Record contract c's Ether balance before deposit
        uint256 cBalanceBefore = address(c).balance;

        // Deposit Ether into c by invoking fallback via a direct call with value
        (bool sentDeposit, ) = address(c).call{value: depositAmount}("");
        require(sentDeposit);

        // After deposit, recorded balance should increase by depositAmount
        uint256 afterRecorded = c.balances(address(this));
        uint256 cBalanceAfter = address(c).balance;

        // Sanity: c's on-chain balance increased exactly by depositAmount
        // (this is a precondition-like check to ensure our deposit behaved as expected)
        require(cBalanceAfter == cBalanceBefore + depositAmount);
        require(afterRecorded == beforeRecorded + depositAmount);

        // Now attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recorded balance and contract balance after withdraw attempt
        uint256 recordedAfterWithdraw = c.balances(address(this));
        uint256 cBalanceFinal = address(c).balance;

        // General property:
        // If withdraw succeeded (not reverted) then the recorded balance for this test address must be zero
        // and c's balance must have decreased by at least the recorded amount that was withdrawn (i.e., no funds lost silently).
        // If withdraw reverted, we place no further requirement about balances.
        assert(reverted || (recordedAfterWithdraw == 0 && cBalanceFinal + (afterRecorded) <= cBalanceAfter + 0));
    }

    // Allow receiving Ether for the test contract
    receive() external payable {}
}

