contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs: deposit amount into c (via fallback) and then attempts withdraw;
    // it asserts that if withdraw did not revert then (1) the recorded balance for this contract's address is zero
    // and (2) address(this) gained at most the deposited amount (i.e., c did not send more than it held for this address).
    function run(uint256 deposit) public payable {
        require(address(this).balance >= deposit);

        // initial recorded balance for this test contract as tracked by c
        uint256 beforeRecorded = c.balances(address(this));
        // initial balances
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        // perform deposit to c via fallback. This increases both c.balance and c.balances[this]
        c.f{value: deposit}();

        // record values after deposit, before withdraw
        uint256 midRecorded = c.balances(address(this));
        uint256 midThis = address(this).balance;
        uint256 midC = address(c).balance;

        // Attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecorded = c.balances(address(this));
        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;

        // General rule asserted for all inputs:
        // If withdraw succeeded then (A) the recorded balance for this address is cleared to zero,
        // and (B) the account's Ether did not increase by more than the amount that was recorded for it before withdraw (i.e., midRecorded).
        // We express (B) as: afterThis - midThis <= midRecorded. To avoid underflow in assert, rearrange to afterThis <= midThis + midRecorded.
        assert(reverted || (afterRecorded == 0 && afterThis <= midThis + midRecorded));
    }

    // allow receiving Ether when c calls back
    receive() external payable {}
}

