    //  - depositAmount: amount of wei to send to c via fallback
    // No precondition on depositAmount except we must have the Ether in this contract.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Record contract balance before any actions
        uint256 cBalanceBefore = address(c).balance;

        // Deposit to c via fallback by sending Ether
        (bool sentDeposit, ) = address(c).call{value: depositAmount}("");
        require(sentDeposit);

        // After deposit, read recorded balance for this test contract's address
        uint256 recordedAfterDeposit = c.balances(address(this));

        // Attempt withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdraw() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read recorded balance and c balance after withdraw attempt
        uint256 recordedAfter = c.balances(address(this));
        uint256 cBalanceAfter = address(c).balance;

        // General rule:
        // If withdraw did not revert, then recorded balance for this address must be zero
        // and the contract's balance must have decreased by at least the amount that was recordedAfterDeposit
        // If withdraw reverted, no requirement on balances (other than they are consistent values)
        assert(
