                // Ensure that c's balance decreased by at least recordedAfterDeposit (the amount the contract thought it owed)
                // Use <= to avoid underflow issues: cBalanceAfter + recordedAfterDeposit <= cBalanceBefore + depositAmount
                cBalanceAfter + recordedAfterDeposit <= cBalanceBefore + depositAmount
            )
        );
    }

